odels();npRenderPreview()});$('#npClearModels')&&($('#npClearModels').onclick=()=>{np.selectedModels.clear();np.pickedVariants.clear();npRenderModels();npRenderPreview()});$('#npQuickCategory')&&($('#npQuickCategory').onclick=async()=>{const name=prompt('نام دسته‌بندی جدید');if(!name)return;alert('افزودن سریع از Route '+routes.categoriesQuickStore+' و Permission واقعی آن استفاده می‌کند؛ در این نسخه برای جلوگیری از تغییر ناخواسته DB از مودال draft اجرا نمی‌شود.')});$('#npQuickModel')&&($('#npQuickModel').onclick=()=>alert('افزودن سریع مدل از Route '+routes.modelListsQuickStore+' و Permission واقعی مدل‌لیست استفاده می‌کند.'));$('#addNewProductRow')&&($('#addNewProductRow').onclick=npAddRows);syncSource();if(init.customerId)loadInvoices();renderItems();
